// ============================================
// VALIDATE PRESIGN REQUEST & GET SERVICE TOKEN
// ============================================

const body = $input.first().json.body || $input.first().json;

// Extract required fields
const file_id = body.file_id;
const tenant_id = body.tenant_id;
const valid_seconds = body.valid_seconds || 3600;

// Validate required fields
if (!file_id) {
  return {
    error: true,
    status: 400,
    message: 'missing_file_id',
    detail: 'file_id is required'
  };
}

if (!tenant_id) {
  return {
    error: true,
    status: 400,
    message: 'missing_tenant_id',
    detail: 'tenant_id is required for token routing'
  };
}

// Validate valid_seconds range
if (valid_seconds < 60 || valid_seconds > 7200) {
  return {
    error: true,
    status: 400,
    message: 'invalid_valid_seconds',
    detail: 'valid_seconds must be between 60 and 7200'
  };
}

// Get service token for tenant
const serviceToken = $env[`SERVICE_TOKEN_${tenant_id}`];
if (!serviceToken) {
  return {
    error: true,
    status: 401,
    message: 'unknown_tenant',
    detail: `No service token configured for tenant: ${tenant_id}`
  };
}

// Return validated data
return {
  error: false,
  file_id: file_id,
  tenant_id: tenant_id,
  valid_seconds: valid_seconds,
  service_token: serviceToken,
  api_base_url: $env.CHAT_API_BASE_URL || 'http://localhost:8080'
};

// ============================================
// VALIDATE DELETE REQUEST & GET SERVICE TOKEN
// ============================================

const body = $input.first().json.body || $input.first().json;

// Extract required fields
const file_id = body.file_id;
const tenant_id = body.tenant_id;

// Validate required fields
if (!file_id) {
  return {
    error: true,
    status: 400,
    message: 'missing_file_id',
    detail: 'file_id is required'
  };
}

if (!tenant_id) {
  return {
    error: true,
    status: 400,
    message: 'missing_tenant_id',
    detail: 'tenant_id is required for token routing'
  };
}

// Get service token for tenant
const serviceToken = $env[`SERVICE_TOKEN_${tenant_id}`];
if (!serviceToken) {
  return {
    error: true,
    status: 401,
    message: 'unknown_tenant',
    detail: `No service token configured for tenant: ${tenant_id}`
  };
}

// Return validated data
return {
  error: false,
  file_id: file_id,
  tenant_id: tenant_id,
  service_token: serviceToken,
  api_base_url: $env.CHAT_API_BASE_URL || 'http://localhost:8080'
};

// ============================================
// PROCESS PRESIGN API RESPONSE
// ============================================

const response = $input.first().json;
const validatedData = $('Validate Presign').first().json;

// Check for HTTP errors (response might have error status)
if (response.error || response.statusCode >= 400) {
  return {
    success: false,
    status: response.statusCode || 500,
    error: response.error || 'api_error',
    detail: response.message || response.detail || 'Unknown error from chat.api'
  };
}

// Success - return presigned URL data
return {
  success: true,
  status: 200,
  file_id: response.file_id || validatedData.file_id,
  download_url: response.download_url,
  expires_at: response.expires_at,
  valid_seconds: response.valid_seconds || validatedData.valid_seconds
};

// ============================================
// PROCESS DELETE API RESPONSE
// ============================================

const response = $input.first().json;
const validatedData = $('Validate Delete').first().json;

// Check for HTTP errors
if (response.error || (response.statusCode && response.statusCode >= 400 && response.statusCode !== 404)) {
  return {
    success: false,
    status: response.statusCode || 500,
    error: response.error || 'api_error',
    detail: response.message || response.detail || 'Unknown error from chat.api'
  };
}

// Success (204 No Content) or already deleted (404 is idempotent)
return {
  success: true,
  status: 204,
  file_id: validatedData.file_id,
  deleted: true
};
